                debtAmount = ad.tokens[0] == _token0(pool0)
                    ? Helper.getAmountInV2(ad.amountIn, r0, r1)
                    : Helper.getAmountInV2(ad.amountIn, r1, r0);
            }
            profit = current > debtAmount ? current - debtAmount : 0;
        }
