        for (uint256 i = 0; i < probes.length; ++i) {
            uint256 amt = probes[i];
            uint256 profit = _quoteProfit(quoter, tokens, pools, fees, amt);

            if (profit > bestProfit) {
                bestProfit = profit;
                bestAmt = amt;
            }
        }

