            if (_isUniswapV3(pools[i])) {  // adjust based on your Helper
                // Use V3 Quoter
                (current,,,) = IQuoter(quoter).quoteExactInputSingle(
                    IQuoter.QuoteExactInputSingleParams({
                        tokenIn: tokens[i],
                        tokenOut: tokens[i+1],
                        amountIn: current,
                        fee: fees[i],
                        sqrtPriceLimitX96: 0
                    })
                );
