                // V2 simulation using your Helper
                (uint112 r0, uint112 r1,) = IUniswapV2Pair(pools[i]).getReserves(); // assuming pool address
                address t0 = _token0(pools[i]); // adjust as needed
                current = tokens[i] == t0 
                    ? getAmountOutV2(current, r0, r1)
                    : getAmountOutV2(current, r1, r0);
            }
        }

        // For cyclic arb: profit = final output - input
        profit = current > amountIn ? current - amountIn : 0;
    }
